import Foundation
import TimerCore

public struct Session: Codable, Sendable { public var kind: Countdown.Kind; public var start: Date; public var end: Date }

/// Appends finished sessions to one JSON file per day. Writes are atomic.
public struct Store {
    public let folder: URL
    public init(folder: URL) { self.folder = folder }

    public func append(_ session: Session) throws {
        var all = try load(day: session.start)
        all.append(session)
        try JSONEncoder().encode(all).write(to: file(for: session.start), options: .atomic)
    }

    public func load(day: Date) throws -> [Session] {
        guard let data = try? Data(contentsOf: file(for: day)) else { return [] }
        return try JSONDecoder().decode([Session].self, from: data)
    }

    func file(for day: Date) -> URL {
        folder.appending(path: day.formatted(.iso8601.year().month().day()) + ".json")
    }
}

import Foundation
import TimerCore
import SessionStore

let store = Store(folder: URL.applicationSupportDirectory.appending(path: "FocusTimer"))
switch CommandLine.arguments.dropFirst().first {
case "start":
    let countdown = Countdown(kind: .focus, length: .seconds(25 * 60), started: .now)
    while !countdown.isFinished(now: .now) { sleep(1) }
    try store.append(Session(kind: .focus, start: countdown.started, end: .now))
    print("Done. Take a break.")
case "log":
    for s in try store.load(day: .now) { print(s.kind.rawValue, s.start.formatted(date: .omitted, time: .shortened)) }
default:
    print("usage: focus start | log")
}

